referenceSolutionTemplate:
#include <stdio.h>
#include <string.h>

/* ===== 开工区：按注释里的规矩写 main ===== */
int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("{a}\n");
        printf("{b}\n");
        return 0;
    }
    if (strcmp(argv[1], "{w}") == 0) {
        printf("{c}\n");
    } else {
        printf("认不得：%s\n", argv[1]);
    }
    return 0;
}
